use verus::prelude::*;

verus! {

    ////////////////////////////////////////////////////////////
    // A specification function that counts the number of `true`
    // elements in a sequence of booleans.
    ////////////////////////////////////////////////////////////
    spec fn count_bool_seq(s: Seq<bool>) -> nat {
        if s.len() == 0 {
            0
        } else {
            let head = if s.index(0) { 1 } else { 0 };
            head + count_bool_seq(s.subseq(1, s.len()))
        }
    }

    ////////////////////////////////////////////////////////////
    // The verified function:
    //
    //   - requires nothing special about `arr`
    //   - ensures the returned `count` is between 0 and arr.len()
    //   - ensures the returned `count` matches the spec count over
    //     the entire array
    ////////////////////////////////////////////////////////////
    fn count_true(arr: &Vec<bool>) -> (count: u64)
        ensures
            // 0 <= count <= arr.len()
            count <= arr.len() as u64,
            // count agrees with the formal definition
            count == count_bool_seq(arr@) as u64
    {
        let mut i: usize = 0;
        let mut cnt: u64 = 0;

        // We iterate over arr by index i
        while i < arr.len() {
            invariant
                // i is always a valid prefix length
                i <= arr.len(),
                // cnt never exceeds the maximum possible
                cnt <= arr.len() as u64,
                // key invariant: cnt agrees with the spec count
                // on the prefix arr@[0..i]
                cnt as nat == count_bool_seq(arr@.subseq(0, i));
            decreases arr.len() - i;

            if arr[i] {
                cnt += 1;
            }
            i += 1;
        }

        // Now i == arr.len(), so the prefix is the whole array:
        assert(cnt as nat == count_bool_seq(arr@.subseq(0, arr.len())));
        // and subseq(0, len) is just arr@ itself
        assert(arr@.subseq(0, arr.len()) == arr@);

        cnt
    }

}